class Solution {
    public boolean equalFrequency(String word) {
        int[] cnt = new int[26];
        for (char ch : word.toCharArray()) cnt[ch - 'a']++;
        for (int i = 0; i < 26; i++) {
            if (cnt[i] == 0) continue;
            cnt[i]--;
            int v = -1; boolean ok = true;
            for (int k = 0; k < 26; k++)
                if (cnt[k] > 0) { if (v == -1) v = cnt[k]; else if (v != cnt[k]) ok = false; }
            cnt[i]++;
            if (ok) return true;
        }
        return false;
    }
}

